function news_gallery(?PDO $pdo,string $kind,string $ownerType,int $ownerId,string $title):string{$batch=mediaBatchFind($pdo,$kind,$ownerType,$ownerId);$images=$batch?mediaBatchImages($pdo,(int)$batch['id']):[];if(!$batch||!$images)return'';ob_start();?><div class="news-gallery card-soft p-3"><img class="news-main-image" src="<?php echo h(mediaBatchImageUrl($batch,$images[0],'md')); ?>" alt="<?php echo h($images[0]['alt_text']?:$title); ?>"><?php if(count($images)>1): ?><div class="news-thumbs"><?php foreach($images as$image): ?><img src="<?php echo h(mediaBatchImageUrl($batch,$image,'xs')); ?>" alt="<?php echo h($image['alt_text']??''); ?>"><?php endforeach; ?></div><?php endif; ?><?php if(!empty($images[0]['caption'])): ?><div class="small text-muted mt-2"><?php echo h($images[0]['caption']); ?></div><?php endif; ?></div><?php return(string)ob_get_clean();}
